arguments.command:
cd /app/work && rm -f req_fallback_sub.jsonl req_chunk*.jsonl req_culprit.jsonl _req_*.jsonl _res_*.jsonl out*.txt; du -sh /app/work /app/submission; ls -la /app/submission; stat -c '%F nlink=%h size=%s' /app/submission/planner.py; echo; python - <<'EOF'
import os, stat
root = "/app/submission"
bad = []
for dirpath, dirnames, filenames in os.walk(root):
    for name in dirnames + filenames:
        p = os.path.join(dirpath, name)
        st = os.lstat(p)
        if stat.S_ISLNK(st.st_mode): bad.append(("symlink", p))
        if not (stat.S_ISDIR(st.st_mode) or stat.S_ISREG(st.st_mode)): bad.append(("special", p))
        if stat.S_ISREG(st.st_mode) and st.st_nlink != 1: bad.append(("nlink", p, st.st_nlink))
print("violations:", bad if bad else "none")
print("total size:", sum(os.lstat(os.path.join(r,f)).st_size for r,d,fs in os.walk(root) for f in fs))
EOF
